export const DEFAULTS=Object.freeze({toneMapping:'ACES',exposure:.92,contrast:1.16,saturation:1.18,environment:.42,ambient:.12,keyIntensity:3.1,keyColor:'#ffedd4',keyX:-190,keyY:210,keyZ:170,fillIntensity:.26,fillColor:'#d6dbff',rimIntensity:1.8,rimColor:'#c9b4ff',shadows:true,shadowSoftness:1.8,ao:true,aoIntensity:1.25,aoRadius:3.5,aoThickness:3,shellColor:'#8a50d6',rearColor:'#efc81c',shellRoughness:.42,shellMetalness:0,clearcoat:.4,clearcoatRoughness:.26,surfaceGrain:.07,metalRoughness:.2,metalness:.95,background:'#f5f4f0',zoom:1});
export const ranges={exposure:[.1,2.5],contrast:[.5,1.8],saturation:[0,2],environment:[0,2],ambient:[0,2],keyIntensity:[0,8],keyX:[-300,300],keyY:[-300,300],keyZ:[-300,300],fillIntensity:[0,5],rimIntensity:[0,5],shadowSoftness:[0,8],aoIntensity:[0,1.5],aoRadius:[.1,15],aoThickness:[.1,10],shellRoughness:[.05,1],shellMetalness:[0,1],clearcoat:[0,1],clearcoatRoughness:[.05,1],surfaceGrain:[0,.3],metalRoughness:[.05,1],metalness:[0,1],zoom:[.6,1.6]};
export function validateSettings(input){const out={...DEFAULTS};for(const key of Object.keys(DEFAULTS)){const v=input[key];if(v===undefined)continue;if(ranges[key]){if(typeof v!=='number'||!Number.isFinite(v))throw new Error(`Invalid ${key}`);out[key]=Math.min(ranges[key][1],Math.max(ranges[key][0],v));}else if(typeof DEFAULTS[key]==='boolean'){if(typeof v!=='boolean')throw new Error(`Invalid ${key}`);out[key]=v;}else if(key==='toneMapping'){if(!['ACES','AgX','Neutral','Linear','None'].includes(v))throw new Error('Unknown tone mapping');out[key]=v;}else {if(typeof v!=='string'||!/^#[0-9a-f]{6}$/i.test(v))throw new Error(`Invalid colour: ${key}`);out[key]=v;}}return out;}
